package example.reservation;
import java.time.LocalDate;
import java.util.UUID;
/** 场地预约应用服务；上限由已确认业务规则约束。 */
public class ReservationService {
  public static final String RULE_CODE = "RESERVATION_WINDOW_8D";
  public static final int MAX_ADVANCE_DAYS = 8;
  private final ReservationRepository repository;
  public ReservationService(ReservationRepository repository) { this.repository = repository; }
  /** 只允许提前八天以内预约；同一用户同一场次再次提交时返回已有记录。 */
  public Reservation create(UUID tenant, UUID workspace, UUID user, String slot, LocalDate day) {
    if (day.isAfter(LocalDate.now().plusDays(MAX_ADVANCE_DAYS))) throw new IllegalArgumentException(RULE_CODE);
    var existing = repository.findActive(tenant, workspace, user, slot);
    if (existing != null) return existing;
    return repository.insert(tenant, workspace, user, slot, day);
  }
}

