package example.reservation;
import java.time.LocalDate;
import java.util.UUID;
/** 仅声明持久化接口；数据库约束由迁移确认，不能推定本接口保证竞争下唯一。 */
public interface ReservationRepository {
  Reservation findActive(UUID tenant, UUID workspace, UUID user, String slot);
  Reservation insert(UUID tenant, UUID workspace, UUID user, String slot, LocalDate day);
}

import axios from 'axios';
/** 身份来自会话；客户端不传入租户与用户身份。 */
export async function createReservation(slot:string) { return axios.post('/api/reservations', {slot}); }
